          visual: { kind: "compare", left: { title: "HTTP request", items: ["POST /items", "GET /items/:id", "PUT or PATCH /items/:id", "DELETE /items/:id"] }, right: { title: "SQL statement", items: ["INSERT", "SELECT", "UPDATE", "DELETE"] } },
